"src/shared/exam.js":function(module,exports,__require){
'use strict';
const data=__require("src/data/exam-hard.json");
const banks=[__require("src/data/exam-reunion.json"),__require("src/data/exam-memory.json"),data];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize=s=>String(s??'').normalize('NFKC').toLocaleLowerCase('en').replace(/\s+/g,'').trim();
function correct(q,value){
 if(q.type==='choice')return Number.isInteger(value)&&value===q.answer;
 const n=normalize(value);return n!==''&&[q.answer,...(q.aliases||[])].some(a=>normalize(a)===n);
}
function answered(q,value){return q.type==='choice'?Number.isInteger(value)&&value>=0&&value<q.choices.length:normalize(value)!=='';}
function grade(answers,bank=data){const rows=bank.questions.map(q=>({id:q.id,answered:answered(q,answers[q.id]),correct:correct(q,answers[q.id])}));return {rows,count:rows.filter(r=>r.correct).length,score:rows.filter(r=>r.correct).length*bank.points,blank:rows.filter(r=>!r.answered).length};}
function shuffledChoices(random=Math.random,bank=data){return bank.questions.map(q=>{const a=(q.choices||[]).map((_,i)=>i);for(let i=a.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;});}
function printQuestions(order,name='',bank=data){return __require("src/shared/exam-layout.js").papers((q,i)=>`<section class="exam-print-question"><h3>${i+1}. ${esc(q.prompt)} <small>[4점]</small></h3>${q.type==='choice'?(order?order[i]:q.choices.map((_,n)=>n)).map((v,n)=>`<p>${['①','②','③','④'][n]} ${esc(q.choices[v])}</p>`).join(''):'<p class="exam-print-answer">답: <span></span></p>'}</section>`,name,bank);}
module.exports={data,banks,esc,normalize,correct,answered,grade,shuffledChoices,printQuestions};

},
